import assert from'node:assert/strict';import{writeFileSync,readFileSync,mkdirSync,readdirSync,lstatSync,mkdtempSync,rmSync}from'node:fs';import{join,resolve,delimiter}from'node:path';import{tmpdir}from'node:os';import{spawnSync}from'node:child_process';import{createHash}from'node:crypto';import{withProject,traceMd,ledgerRow,requirement}from'./project.mjs';import{readDocuments}from'../../../packages/trace/dist/index.js';
const root=process.cwd(),scratch=mkdtempSync(join(tmpdir(),'loomake-trace-scale-')),rows=[];const sha=v=>createHash('sha256').update(v).digest('hex');
const snapshot=folder=>Object.fromEntries(readdirSync(folder,{withFileTypes:true}).flatMap(e=>{const p=join(folder,e.name);assert(!e.isSymbolicLink());return e.isDirectory()?Object.entries(snapshot(p)).map(([f,v])=>[join(e.name,f),v]):[[e.name,{bytes:lstatSync(p).size,sha256:sha(readFileSync(p))}]]}));
const preload=join(scratch,'metrics.cjs');writeFileSync(preload,"process.on('exit',()=>require('node:fs').writeFileSync(process.env.LOOMAKE_PROFILE_OUTPUT,JSON.stringify({peakCliRssBytes:process.resourceUsage().maxRSS*1024})));\n");
try{
 for(const[requirements,evidenceCount]of[[10,1],[100,5],[500,20]]){
 const ids=Array.from({length:requirements},(_,i)=>`REQ-${String(i+1).padStart(3,'0')}`);const trace=traceMd({ledger:ids.map(id=>ledgerRow(id))});const spec=['## ADDED Requirements','',...ids.map(id=>requirement(`振る舞い ${id}`,{source:`Source: ${id}`}))].join('\n');
 withProject({trace,spec},project=>{
 const directory=join(project,'.loomake/evidence/c1');mkdirSync(directory,{recursive:true});const documents=readDocuments(join(project,'openspec/changes/c1'));
 const coverage=Object.fromEntries(ids.map(id=>[id,['tests/report.test.ts']]));for(let index=0;index<evidenceCount;index++)writeFileSync(join(directory,`${index}.json`),JSON.stringify({schemaVersion:1,change:'c1',sha:(index+1).toString(16).padStart(40,'0'),recordedAt:new Date(Date.UTC(2026,9,24,0,0,index)).toISOString(),committedAt:'2026-10-24T00:00:00.000Z',verify:{schemaVersion:'1.0.0',change:'c1',mode:'done',ok:true,results:[],coverage},documents}));
 const before=snapshot(project);const outputs={};for(const format of['md','json'])for(let attempt=1;attempt<=3;attempt++){
 const metrics=join(scratch,`${requirements}-${format}-${attempt}.json`);const started=performance.now();const ran=spawnSync('python3',[join(root,'scripts/deny-network.py'),process.execPath,'--require',preload,join(root,'packages/cli/dist/cli.js'),'trace','report','--change','c1','--format',format],{cwd:project,env:{...process.env,LOOMAKE_PROFILE_OUTPUT:metrics},encoding:'utf8',timeout:15000,maxBuffer:16*1024*1024});const wallMs=performance.now()-started;
 assert.equal(ran.error,undefined);assert.equal(ran.status,0,ran.stdout+ran.stderr);if(format==='json'){const v=JSON.parse(ran.stdout);assert.equal(v.rows.length,requirements);assert.deepEqual(v.rows.map(r=>r.id),ids);assert.equal(v.evidence.sha,evidenceCount.toString(16).padStart(40,'0'));assert(v.rows.every(r=>r.result==='合格'&&r.tests[0]==='tests/report.test.ts'));}else{assert(ran.stdout.includes('# 検収レポート：c1'));for(const id of ids)assert(ran.stdout.includes(`| ${id} |`));}
 if(outputs[format])assert.equal(ran.stdout,outputs[format]);else outputs[format]=ran.stdout;assert.deepEqual(snapshot(project),before);
 rows.push({requirements,evidenceCount,format,attempt,wallMs,...JSON.parse(readFileSync(metrics,'utf8')),stdoutBytes:Buffer.byteLength(ran.stdout),stderrBytes:Buffer.byteLength(ran.stderr),outputSha256:sha(ran.stdout),logicalFixtureBytes:Object.values(before).reduce((n,v)=>n+v.bytes,0),logicalBytesAdded:0,inputAndEvidenceUnchanged:true,networkFilter:'Linux seccomp via deny-network.py',withinExistingFiveSecondTimeLimit:wallMs<5000});
 }
 });
 }
 const files=['packages/cli/dist/cli.js','packages/cli/dist/main.js','packages/trace/dist/report.js','packages/trace/dist/documents.js','packages/trace/dist/evidence.js','scripts/deny-network.py','packages/kit/test/project.ts'];
 const result={scope:'Actual compiled trace report CLI in fresh processes under network denial; synthetic saved evidence; fixture setup excluded, process and seccomp startup included',sourceCommit:'current merged source',platform:process.platform,arch:process.arch,node:process.version,limits:['Linux ARM64 host only; three attempts per scale and format.','RSS covers the CLI process, excluding the Python launcher.','Logical fixture sizes exclude physical allocation and data outside the fixture.','No real test runner, real engine or remote GitHub operation was used.'],inputs:Object.fromEntries(files.filter(f=>{try{readFileSync(join(root,f));return true;}catch{return false;}}).map(f=>[f,sha(readFileSync(join(root,f)))])),probeSource:readFileSync(new URL(import.meta.url),'utf8'),rows};writeFileSync(resolve('.loomake/quality/edge-probes/trace-cli-scale-results.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(rows.map(r=>({requirements:r.requirements,evidence:r.evidenceCount,format:r.format,ms:Math.round(r.wallMs),rssMiB:Math.round(r.peakCliRssBytes/1024/1024),bytes:r.stdoutBytes}))));
}catch(error){console.error(error);process.exitCode=1;}finally{rmSync(scratch,{recursive:true,force:true});}
